const src = img.src;
/* 缓存按 **src** 命中，不能只看 img 上有没有 __decoded：同一个 Image 对象换 src
   （出图脚本平铺素材时就这么干）在浏览器里会重新解码，按对象缓存会把第一张图的
   像素发给后面所有 src → 整张平铺图全是同一张。 */
if (img.__decoded && img.__decodedSrc === src) return img.__decoded;

